import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Il ruolo dei postulati","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/ff/ffec.md","filePath":"lezioni/f_geometria-del-piano-euclideo/ff/ffec.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/ff/ffec.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="il-ruolo-dei-postulati" tabindex="-1">Il ruolo dei postulati <a class="header-anchor" href="#il-ruolo-dei-postulati" aria-label="Permalink to “Il ruolo dei postulati”">​</a></h1><p>Quindi si giunge alla conclusione che, a seconda di come prendo i postulati io posso costruire un edificio logico perfettamente coerente, ma non posso dire se esso sia vero o falso; allora ciò che è importante non sono gli oggetti su cui costruisco, ma le interrelazioni che esistono fra tali oggetti: la matematica deve studiare le relazioni più che le proprietà; diceva Hilbert: &quot;Non importa su cosa si studia, prima studiamo poi definiremo gli oggetti dello studio&quot;</p><p>Vedi i <a href="./ffeca.html">boccali di birra</a></p><hr><p>Non solo, ma se il discorso è valido per la geometria cosa succede nell&#39;algebra e nell&#39;aritmetica? Gli anni successivi videro gli sforzi dei matematici per poter ricostruire le basi delle matematiche (chiamiamole così visto che è possibile costruirne tante), con Peano per i postulati dell&#39;aritmetica, con la teoria degli insiemi, con la logica</p><hr><p><strong>La geometria Euclidea, comunque, anche se non va troppo d&#39;accordo con il mondo reale, va benissimo finché l&#39;applichiamo al mondo di tutti i giorni, per la nostra esperienza quotidiana e pertanto si continua a studiarla ed applicarla, fermo restando che, se si vogliono studiare dei fenomeni di tipo atomico, astronomico e/o relativistico, dovremo utilizzare altri modelli matematici</strong></p><hr><p>Allora quale principio potrei mettere come base per studiare la geometria? Si può studiare la geometria ponendo cura a cosa resta fisso se applico delle trasformazioni ed ottengo allora la geometria isometrica (che coincide con l&#39;euclidea), la geometria affine, la geometria proiettiva, eccetera; nasce in questi anni dal programma di Erlangen (1873) la geometria delle trasformazioni che (spero) vedremo in un futuro capitolo (anche perché sempre più spesso è materia d&#39;esame nei licei scientifici)</p><hr>`,10)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};